import React from "react";

export const PageLoading: React.FC<{ label?: string }> = ({ label = "Loading…" }) => <div role="status" aria-live="polite" className="grid min-h-56 place-items-center rounded-3xl border border-slate-200 bg-white p-8 text-center shadow-sm"><div><span aria-hidden="true" className="mx-auto block h-9 w-9 animate-spin rounded-full border-4 border-blue-100 border-t-blue-600" /><p className="mt-4 text-sm font-medium text-slate-500">{label}</p></div></div>;

export const PageEmpty: React.FC<{ title: string; description: string; action?: React.ReactNode }> = ({ title, description, action }) => <section className="grid min-h-64 place-items-center rounded-3xl border border-dashed border-slate-300 bg-white p-8 text-center"><div className="max-w-sm"><span aria-hidden="true" className="grid h-12 w-12 place-items-center rounded-2xl bg-blue-50 text-xl text-blue-600 mx-auto">+</span><h2 className="mt-4 text-lg font-black text-slate-950">{title}</h2><p className="mt-2 text-sm leading-6 text-slate-500">{description}</p>{action && <div className="mt-5">{action}</div>}</div></section>;

export const PageError: React.FC<{ message: string; onRetry?: () => void }> = ({ message, onRetry }) => <section role="alert" className="rounded-3xl border border-red-100 bg-red-50 p-7 text-center"><h2 className="font-black text-slate-950">We could not load this yet.</h2><p className="mt-2 text-sm text-slate-600">{message}</p>{onRetry && <button onClick={onRetry} className="mt-5 rounded-xl bg-slate-950 px-4 py-2.5 text-sm font-bold text-white hover:bg-blue-700">Try again</button>}</section>;
